svg.script:
(function () {
  var W = 4, CELL = 79, GAP = 8, STEP = 87;
  var tiles = document.getElementById('tiles');
  var scoreT = document.getElementById('score'), overlay = document.getElementById('overlay');
  var grid = [], score = 0, over = false, won = false;
  var COLORS = {
    2:'#333a47', 4:'#3d4656', 8:'#00a06a', 16:'#00c17e', 32:'#00ff9c',
    64:'#7dffc4', 128:'#ffd166', 256:'#ff9f1c', 512:'#ff6b6b', 1024:'#f43f5e', 2048:'#f43f5e'
  };

  function empty() {
    grid = []; for (var i = 0; i < W; i++) grid.push([0, 0, 0, 0]);
    score = 0; over = false; won = false;
    scoreT.textContent = 'Score: 0';
    overlay.textContent = 'Swipe or arrow keys to move';
    overlay.setAttribute('fill', '#f4f4f5');
  }

  function spawn() {
    var cells = [];
    for (var i = 0; i < W; i++) for (var j = 0; j < W; j++) if (!grid[i][j]) cells.push([i, j]);
    if (!cells.length) return;
    var c = cells[Math.floor(Math.random() * cells.length)];
    grid[c[0]][c[1]] = Math.random() < 0.9 ? 2 : 4;
  }

  function slide(a) {
    var out = [];
    for (var i = 0; i < a.length; i++) if (a[i]) out.push(a[i]);
    var merged = [];
    for (var i = 0; i < out.length; i++) {
      if (i + 1 < out.length && out[i] === out[i + 1]) { merged.push(out[i] * 2); score += out[i] * 2; i++; }
      else merged.push(out[i]);
    }
    while (merged.length < W) merged.push(0);
    return merged;
  }

  function move(dir) {
    var moved = false;
    for (var i = 0; i < W; i++) {
      var r, c, dr, dc;
      if (dir === 'up') { r = 0; c = i; dr = 1; dc = 0; }
      else if (dir === 'down') { r = W - 1; c = i; dr = -1; dc = 0; }
      else if (dir === 'left') { r = i; c = 0; dr = 0; dc = 1; }
      else { r = i; c = W - 1; dr = 0; dc = -1; }
      var a = [];
      for (var k = 0; k < W; k++) a.push(grid[r + dr * k][c + dc * k]);
      var na = slide(a);
      for (var k = 0; k < W; k++) {
        if (grid[r + dr * k][c + dc * k] !== na[k]) moved = true;
        grid[r + dr * k][c + dc * k] = na[k];
      }
    }
    if (moved) { spawn(); scoreT.textContent = 'Score: ' + score; checkEnd(); draw(); }
  }

  function checkEnd() {
    for (var i = 0; i < W; i++) for (var j = 0; j < W; j++) {
      if (grid[i][j] === 2048 && !won) { won = true; overlay.textContent = '2048! You did it · tap to continue'; }
      if (!grid[i][j]) return;
      if (j + 1 < W && grid[i][j] === grid[i][j + 1]) return;
      if (i + 1 < W && grid[i][j] === grid[i + 1][j]) return;
    }
    over = true;
    overlay.textContent = 'Game over · tap to restart';
    overlay.setAttribute('fill', '#ff4b4b');
  }

  function draw() {
    while (tiles.firstChild) tiles.removeChild(tiles.firstChild);
    for (var i = 0; i < W; i++) for (var j = 0; j < W; j++) {
      var x = j * STEP, y = i * STEP;
      if (!grid[i][j]) {
        var bg = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        bg.setAttribute('x', x); bg.setAttribute('y', y);
        bg.setAttribute('width', CELL); bg.setAttribute('height', CELL);
        bg.setAttribute('rx', 6); bg.setAttribute('fill', '#1a1f2a');
        tiles.appendChild(bg);
        continue;
      }
      var v = grid[i][j];
      var t = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      t.setAttribute('x', x); t.setAttribute('y', y);
      t.setAttribute('width', CELL); t.setAttribute('height', CELL);
      t.setAttribute('rx', 6);
      t.setAttribute('fill', COLORS[v] || '#f43f5e');
      tiles.appendChild(t);
      var s = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      var fs = ('' + v).length <= 2 ? 30 : ('' + v).length === 3 ? 24 : 20;
      s.setAttribute('x', x + CELL / 2); s.setAttribute('y', y + CELL / 2 + 10);
      s.setAttribute('text-anchor', 'middle');
      s.setAttribute('font-size', fs);
      s.setAttribute('font-weight', 'bold');
      s.setAttribute('fill', v >= 64 ? '#0a0a12' : '#f4f4f5');
      s.textContent = v;
      tiles.appendChild(s);
    }
  }

  document.addEventListener('keydown', function (e) {
    var k = e.key;
    if (k === 'ArrowUp' || k === 'w' || k === 'W') { e.preventDefault(); move('up'); }
    else if (k === 'ArrowDown' || k === 's' || k === 'S') { e.preventDefault(); move('down'); }
    else if (k === 'ArrowLeft' || k === 'a' || k === 'A') { e.preventDefault(); move('left'); }
    else if (k === 'ArrowRight' || k === 'd' || k === 'D') { e.preventDefault(); move('right'); }
    else if (k === 'r' || k === 'R') { empty(); spawn(); spawn(); draw(); }
  });

  // --- Touch controls (mobile) ---
  var tsx = 0, tsy = 0;
  document.addEventListener('touchstart', function (e) { tsx = e.touches[0].clientX; tsy = e.touches[0].clientY; }, {passive: true});
  document.addEventListener('touchmove', function (e) { e.preventDefault(); }, {passive: false});
  document.addEventListener('touchend', function (e) {
    var t = e.changedTouches[0];
    var dx = t.clientX - tsx, dy = t.clientY - tsy;
    if (Math.abs(dx) < 24 && Math.abs(dy) < 24) { if (over) { empty(); spawn(); spawn(); draw(); } return; }
    if (Math.abs(dx) > Math.abs(dy)) move(dx > 0 ? 'right' : 'left');
    else move(dy > 0 ? 'down' : 'up');
  }, {passive: false});

  empty(); spawn(); spawn(); draw();
})();
